-- Regenerate palettes.lua and colors/rex-*.lua from Rex's bundled themes.json.
-- Run from anywhere after a Rex update that adds or changes themes:
--   nvim -l nvim/vendor/rex-themes.nvim/scripts/sync.lua [path/to/themes.json]

-- Rex theme ids to generate. Add an id here and re-run to bring another theme in.
local keep = { "abyssal-trench", "merino-dark", "merino-light" }

local root = vim.fs.dirname(vim.fs.dirname(vim.fs.normalize(vim.fn.fnamemodify(arg[0], ":p"))))
local rel = "Contents/Resources/SuperUI_SuperDesignTokens.bundle/Contents/Resources/themes.json"

local source = arg[1]
if not source then
  for _, app in ipairs(vim.fn.glob("/Applications/Rex*.app", false, true)) do
    if vim.uv.fs_stat(app .. "/" .. rel) then
      source = app .. "/" .. rel
      break
    end
  end
end
assert(source, "themes.json not found; pass its path as the first argument")

local themes = vim.tbl_filter(function(t)
  return vim.tbl_contains(keep, t.id)
end, vim.json.decode(table.concat(vim.fn.readfile(source), "\n")))
for _, id in ipairs(keep) do
  assert(
    vim.iter(themes):any(function(t)
      return t.id == id
    end),
    "Theme not found in Rex: " .. id
  )
end
table.sort(themes, function(a, b)
  return a.id < b.id
end)

local out = {
  "-- Generated by scripts/sync.lua from Rex's themes.json. Do not edit by hand.",
  "-- ANSI indices are zero-based, matching the terminal themes.",
  "-- stylua: ignore",
  "return {",
}
for _, t in ipairs(themes) do
  local s = t.source
  assert(#s.ansi == 16, t.id .. ": expected 16 ANSI colours")
  local ansi = vim.tbl_map(function(c)
    return ('"%s"'):format(c:lower())
  end, s.ansi)
  vim.list_extend(out, {
    ('  ["%s"] = {'):format(t.id),
    ('    name = "%s",'):format(t.name),
    ('    appearance = "%s",'):format(t.appearance),
    ('    background = "%s",'):format(s.background:lower()),
    ('    foreground = "%s",'):format(s.foreground:lower()),
    ('    cursor = "%s",'):format(s.cursor:lower()),
    ('    cursor_text = "%s",'):format(s.cursorText:lower()),
    ('    selection_background = "%s",'):format(s.selectionBackground:lower()),
    ('    selection_foreground = "%s",'):format(s.selectionForeground:lower()),
    "    ansi = {",
    "      [0] = " .. table.concat(ansi, ", ", 1, 4) .. ",",
    "      " .. table.concat(ansi, ", ", 5, 8) .. ",",
    "      " .. table.concat(ansi, ", ", 9, 12) .. ",",
    "      " .. table.concat(ansi, ", ", 13, 16) .. ",",
    "    },",
    "  },",
  })
end
out[#out + 1] = "}"
vim.fn.writefile(out, root .. "/lua/rex_themes/palettes.lua")

-- One colors/ file per theme so `:colorscheme rex-<Tab>` lists them all.
vim.fn.mkdir(root .. "/colors", "p")
for _, old in ipairs(vim.fn.glob(root .. "/colors/rex-*.lua", false, true)) do
  os.remove(old)
end
for _, t in ipairs(themes) do
  vim.fn.writefile({ ('require("rex_themes").load("%s")'):format(t.id) }, ("%s/colors/rex-%s.lua"):format(root, t.id))
end

print(("Synced %d themes from %s"):format(#themes, source))
